using System;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;
public static class Scene2DrawerHighlights{
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void Initialize(){SceneManager.sceneLoaded-=Bind;SceneManager.sceneLoaded+=Bind;Bind(SceneManager.GetActiveScene(),LoadSceneMode.Single);}
 public static void Bind(Scene scene,LoadSceneMode mode){if(!scene.IsValid()||!string.Equals(scene.name.Replace(" ",""),"scene2",StringComparison.OrdinalIgnoreCase))return;var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var housing=KeyDrawerUnlock.FindPianoHousing(scene);foreach(var name in new[]{"bottona","Drawer Complete Shell"}){var t=all.FirstOrDefault(x=>string.Equals(x.name.Trim(),name,StringComparison.OrdinalIgnoreCase));if(!t)continue;var mesh=t.GetComponent<MeshFilter>();if(!mesh||!mesh.sharedMesh)continue;if(!t.GetComponent<Collider>())t.gameObject.AddComponent<MeshCollider>().sharedMesh=mesh.sharedMesh;var h=t.GetComponent<HoverScanHighlight>();if(name=="Drawer Complete Shell"){if(h)h.enabled=false;continue;}if(!h)h=t.gameObject.AddComponent<HoverScanHighlight>();h.ConfigureScene2();h.Configure(6,100);h.ConfigureOcclusionHousing(housing);}}
}
